package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/go-sql-driver/mysql"
)

var db *sql.DB

type Product struct {
	ID          int     `json:"id"`
	Name        string  `json:"name"`
	Description string  `json:"description"`
	Price       float64 `json:"price"`
	Category    string  `json:"category"`
}

func init() {
	dsn := os.Getenv("MYSQL_DSN")
	if dsn == "" {
		dsn = "appuser:apppass@tcp(127.0.0.1:3306)/shopdb"
	}
	var err error
	db, err = sql.Open("mysql", dsn)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(10)
}

// searchProducts handles product search with category filter
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortBy := r.URL.Query().Get("sort")

	if category == "" {
		http.Error(w, "category parameter required", http.StatusBadRequest)
		return
	}

	// Validate sort parameter - only allow known columns
	allowedSorts := map[string]bool{"name": true, "price": true, "id": true}
	if sortBy != "" && !allowedSorts[sortBy] {
		sortBy = "id"
	}
	if sortBy == "" {
		sortBy = "id"
	}

	// Build query - category is user-controlled and concatenated directly
	query := fmt.Sprintf("SELECT id, name, description, price, category FROM products WHERE category = '%s' ORDER BY %s", category, sortBy)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Description, &p.Price, &p.Category); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// getProductDetail returns a single product by ID
func getProductDetail(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Query().Get("id")
	if id == "" {
		http.Error(w, "id required", http.StatusBadRequest)
		return
	}

	// This one uses parameterized query correctly
	var p Product
	err := db.QueryRow("SELECT id, name, description, price, category FROM products WHERE id = ?", id).Scan(&p.ID, &p.Name, &p.Description, &p.Price, &p.Category)
	if err != nil {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(p)
}

// healthCheck endpoint for load balancer
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	// Log request metadata for debugging
	log.Printf("health check from %s, X-Amzn-Trace-Id: %s", r.RemoteAddr, r.Header.Get("X-Amzn-Trace-Id"))
	fmt.Fprint(w, "ok")
}

// adminResetCache is an internal endpoint
func adminResetCache(w http.ResponseWriter, r *http.Request) {
	authHeader := r.Header.Get("X-Internal-Auth")
	if !strings.HasPrefix(authHeader, "Bearer int_") {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	// Reset prepared statement cache
	db.SetMaxOpenConns(0)
	db.SetMaxOpenConns(10)
	fmt.Fprint(w, "cache reset")
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/api/products/detail", getProductDetail)
	http.HandleFunc("/health", healthCheck)
	http.HandleFunc("/internal/reset-cache", adminResetCache)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
